import javax.net.ssl.*
import java.security.cert.X509Certificate

// Minimal SSL bypass for corporate networks
try {
    def trustManager = new X509TrustManager() {
        X509Certificate[] getAcceptedIssuers() { null }
        void checkClientTrusted(X509Certificate[] certs, String authType) {}
        void checkServerTrusted(X509Certificate[] certs, String authType) {}
    }

    def sslContext = SSLContext.getInstance("TLS")
    sslContext.init(null, [trustManager] as TrustManager[], null)
    HttpsURLConnection.setDefaultSSLSocketFactory(sslContext.socketFactory)
    HttpsURLConnection.setDefaultHostnameVerifier({ hostname, session -> true } as HostnameVerifier)

    println "SSL verification disabled"
} catch (Exception e) {
    println "Warning: SSL bypass failed: ${e.message}"
}

import javax.net.ssl.*
import java.security.cert.X509Certificate
import java.security.SecureRandom

// SSL bypass for corporate networks - disables certificate validation
allprojects {
    buildscript {
        repositories.all { ArtifactRepository repo ->
            if (repo instanceof UrlArtifactRepository) {
                def urlRepo = repo as UrlArtifactRepository
                urlRepo.allowInsecureProtocol = true
            }
        }
    }
    repositories.all { ArtifactRepository repo ->
        if (repo instanceof UrlArtifactRepository) {
            def urlRepo = repo as UrlArtifactRepository
            urlRepo.allowInsecureProtocol = true
        }
    }
}

try {
    def trustAllCerts = [
        new X509TrustManager() {
            X509Certificate[] getAcceptedIssuers() { return null }
            void checkClientTrusted(X509Certificate[] certs, String authType) {}
            void checkServerTrusted(X509Certificate[] certs, String authType) {}
        }
    ] as TrustManager[]

    def sslContext = SSLContext.getInstance("TLS")
    sslContext.init(null, trustAllCerts, new SecureRandom())

    HttpsURLConnection.setDefaultSSLSocketFactory(sslContext.socketFactory)
    HttpsURLConnection.setDefaultHostnameVerifier({ hostname, session -> true } as HostnameVerifier)

    // Also set the default socket factory
    SSLContext.setDefault(sslContext)

    println "✓ SSL certificate verification bypassed for Gradle"
} catch (Exception e) {
    println "✗ Warning: SSL bypass failed: ${e.message}"
    e.printStackTrace()
}

// Apply the init script for SSL handling
apply(from = "init.gradle")

pluginManagement {
    repositories {
        google {
            content {
                includeGroupByRegex("com\\.android.*")
                includeGroupByRegex("com\\.google.*")
                includeGroupByRegex("androidx.*")
            }
        }
        mavenCentral()
        gradlePluginPortal()
        maven {
            url = uri("https://maven.pkg.jetbrains.space/kotlin/p/kotlin/dev")
        }
    }
}
dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {
        google()
        mavenCentral()
    }
}

rootProject.name = "PairUp"
include(":app")

// Apply the init script for SSL handling
apply(from = "init.gradle")

pluginManagement {
    repositories {
        google {
            content {
                includeGroupByRegex("com\\.android.*")
                includeGroupByRegex("com\\.google.*")
                includeGroupByRegex("androidx.*")
            }
        }
        mavenCentral()
        gradlePluginPortal()
        maven {
            url = uri("https://maven.pkg.jetbrains.space/kotlin/p/kotlin/dev")
        }
        // Allow all repositories to use HTTP if needed
        all {
            if (this is UrlArtifactRepository) {
                isAllowInsecureProtocol = true
            }
        }
    }
}
dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {
        google()
        mavenCentral()
        // Allow all repositories to use HTTP if needed
        all {
            if (this is UrlArtifactRepository) {
                isAllowInsecureProtocol = true
            }
        }
    }
}

rootProject.name = "PairUp"
include(":app")
